def transform(grid):
    h=len(grid); w=len(grid[0]); out=[row[:] for row in grid]
    seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]==7 or (r,c) in seen: continue
            color=grid[r][c]; q=[(r,c)]; seen.add((r,c)); cells=[]
            while q:
                y,x=q.pop(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
            r0,r1=min(ys),max(ys); c0,c1=min(xs),max(xs)
            for y,x in cells: out[y][x]=7
            if len(cells)==1:
                for y in range(r0-4,r0+5):
                    for x in range(c0-4,c0+5):
                        if 0<=y<h and 0<=x<w: out[y][x]=color
            else:
                for y in range(r0+1,r1):
                    for x in range(c0+1,c1): out[y][x]=color
                if r1==h-1 and c1==w-1:
                    out[r1-1][c1-1]=7; out[r1-1][c1]=color
    return out
